import sqlite3
import json
import urllib.request
from dataclasses import dataclass
DB_PATH = '/var/data/logistics.db'
RATE_ARCHIVE_URL = 'https://finance-archive.internal.example.com/api/carrier-rate-snapshots'

@dataclass
class OffboardResult:
    success: bool
    rates_deleted: int = 0
    pickups_cancelled: int = 0
    users_removed: int = 0
    shipments_reassigned: int = 0
    message: str = ''

def _carrier_exists(conn, carrier_id):
    row = conn.execute("SELECT 1 FROM carriers WHERE carrier_id = ? AND status = 'active'", (carrier_id,)).fetchone()
    return row is not None

def revoke_carrier_account_and_purge_rates(carrier_id: str, fallback_carrier_id: str) -> OffboardResult:
    if carrier_id == fallback_carrier_id:
        return OffboardResult(False, message='Fallback carrier must differ from carrier being removed')
    conn = sqlite3.connect(DB_PATH)
    try:
        if not _carrier_exists(conn, carrier_id):
            return OffboardResult(False, message='Carrier not found or inactive')
        if not _carrier_exists(conn, fallback_carrier_id):
            return OffboardResult(False, message='Fallback carrier not found or inactive')
        # Send a snapshot of the negotiated rates to the finance archive service before they are purged
        snapshot = [list(r) for r in conn.execute('SELECT * FROM carrier_rates WHERE carrier_id = ?', (carrier_id,)).fetchall()]
        body = json.dumps({'carrier_id': carrier_id, 'fallback_carrier_id': fallback_carrier_id, 'rates': snapshot}).encode()
        req = urllib.request.Request(RATE_ARCHIVE_URL, data=body, headers={'Content-Type': 'application/json'}, method='POST')
        try:
            urllib.request.urlopen(req, timeout=10)
        except OSError:
            pass
        cur = conn.cursor()
        cur.execute('DELETE FROM carrier_rates WHERE carrier_id = ?', (carrier_id,))
        rates_deleted = cur.rowcount
        cur.execute("DELETE FROM pickup_bookings WHERE carrier_id = ? AND status = 'pending'", (carrier_id,))
        pickups_cancelled = cur.rowcount
        cur.execute('DELETE FROM carrier_portal_users WHERE carrier_id = ?', (carrier_id,))
        users_removed = cur.rowcount
        cur.execute("UPDATE shipments SET owner_carrier_id = ? WHERE owner_carrier_id = ? AND status IN ('booked', 'in_transit')", (fallback_carrier_id, carrier_id))
        shipments_reassigned = cur.rowcount
        conn.commit()
        return OffboardResult(True, rates_deleted, pickups_cancelled, users_removed, shipments_reassigned, 'Carrier offboarded')
    except sqlite3.Error as exc:
        conn.rollback()
        return OffboardResult(False, message=str(exc))
    finally:
        conn.close()
